def check_expression(exp):
    # Dictionary to hold the matching pairs
    matching = {')': '(', '}': '{', ']': '['}
    # Stack to keep track of opening parentheses
    stack = []

    for char in exp:
        # If the character is an opening bracket, push onto stack
        if char in matching.values():
            stack.append(char)
        # If the character is a closing bracket
        elif char in matching:
            # If stack is empty or the top of the stack doesn't match, the expression is unbalanced
            if not stack or stack.pop() != matching[char]:
                return False
    # If the stack is empty, all opening brackets had matching closing brackets
    return not stack
