def common_in_nested_lists(nestedlist):
    if not nestedlist:
        return []

    # Flatten the list of lists
    flat_list = [item for sublist in nestedlist for item in sublist]

    # Convert to set to remove duplicates and find common elements
    unique_elements = set(flat_list)

    # Find common elements in the list of lists
    common = set(flat_list[0])
    for sublist in nestedlist[1:]:
        common &= set(sublist)

    # Return the intersection of unique elements and common elements
    return list(common)

