def search(arr):
    # Binary search approach
    left, right = 0, len(arr) - 1
    while left < right:
        mid = (left + right) // 2
        # If mid is even and arr[mid] == arr[mid + 1], or if mid is odd and arr[mid] == arr[mid - 1]
        # then the unique element is in the right half
        if (mid % 2 == 0 and arr[mid] == arr[mid + 1]) or (mid % 2 == 1 and arr[mid] == arr[mid - 1]):
            left = mid + 1
        else:
            right = mid
    return arr[left]

