def maxAverageOfPath(cost):
    n = len(cost)
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = cost[0][0]

    # Initialize first column
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + cost[i][0]

    # Initialize first row
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + cost[0][j]

    # Fill dp table
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + cost[i][j]

    # Calculate maximum average
    max_avg = float(dp[n-1][n-1]) / n
    for i in range(n-1):
        max_avg = max(max_avg, (dp[n-1][i] + dp[i][n-1] - cost[i][i]) / n)

    return max_avg

