def max_sub_array_sum_repeated(a, n, k):
    max_sum = float('-inf')
    current_sum = 0
    prefix_sum = [0]

    for i in range(n):
        prefix_sum.append(prefix_sum[-1] + a[i])

    for start in range(n):
        for end in range(start, n):
            sub_array_sum = prefix_sum[end + 1] - prefix_sum[start]
            current_sum = max(sub_array_sum, current_sum + prefix_sum[(end + 1) % n] - prefix_sum[(start) % n])
            max_sum = max(max_sum, current_sum)

    for _ in range(k - 1):
        max_sum = max(max_sum, prefix_sum[-1] * k)

    return max_sum

