def check_min_heap(arr):
    def heapify(arr, i, n):
        smallest = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < n and arr[left] < arr[smallest]:
            smallest = left

        if right < n and arr[right] < arr[smallest]:
            smallest = right

        if smallest != i:
            arr[smallest], arr[i] = arr[i], arr[smallest]
            heapify(arr, smallest, n)

    n = len(arr)

    # Check heap property for each node starting from the last parent node
    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, i, n)

    # If all elements are in place, the array represents a min heap
    return all(arr[i] >= arr[2 * i + 1] if 2 * i + 1 < n else True for i in range(n // 2))
