def minPath(grid, k):
    N = len(grid)

    # Helper function to get the value of a cell
    def get_value(row, col):
        return grid[row][col] - 1 + (N * N) * (row + 1)

    # Helper function to get the neighbors of a cell
    def get_neighbors(row, col):
        neighbors = []
        if row > 0: neighbors.append((row - 1, col))
        if row < N - 1: neighbors.append((row + 1, col))
        if col > 0: neighbors.append((row, col - 1))
        if col < N - 1: neighbors.append((row, col + 1))
        return neighbors

    # Initialize the memoization table
    memo = {}

    def dfs(row, col, remaining_steps):
        if (row, col, remaining_steps) in memo:
            return memo[(row, col, remaining_steps)]

        if remaining_steps == 1:
            return [get_value(row, col)]

        min_path = []
        for neighbor in get_neighbors(row, col):
            neighbor_row, neighbor_col = neighbor
            path = dfs(neighbor_row, neighbor_col, remaining_steps - 1)
            if path and (path[-1] + 1 < get_value(row, col)):
                if min_path == []:
                    min_path = path + [get_value(row, col)]
                else:
                    min_path = path + [get_value(row, col)] if len(path) < len(min_path) else min_path
        memo[(row, col, remaining_steps)] = min_path
        return min_path

    # Start DFS from the top-left cell
    return dfs(0, 0, k)
