def rearrange_bigger(n):
    digits = list(str(n))
    length = len(digits)

    for i in range(length - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            pivot = i
            break
    else:
        return None  # n is the largest possible number

    for i in range(length - 1, pivot, -1):
        if digits[i] > digits[pivot]:
            replace = i
            break

    digits[pivot], digits[replace] = digits[replace], digits[pivot]
    digits[pivot + 1:] = reversed(digits[pivot + 1:])

    result = int(''.join(digits))
    return result if result > n else None
