def max_sub_array_sum_repeated(a, n, k):
    def max_sub_array(arr):
        max_sum, cur_sum = 0, 0
        for num in arr:
            cur_sum = max(cur_sum + num, num)
            max_sum = max(max_sum, cur_sum)
        return max_sum

    # If k is 1, we can simply call the max_sub_array function once.
    if k == 1:
        return max_sub_array(a)

    # Calculate the sum of the array and the sum of the array without the last element.
    total_sum = sum(a)
    without_last = total_sum - a[n-1]

    # If k is 2, we can calculate the maximum sum of the array as it is, and as it is without the last element.
    if k == 2:
        return max(total_sum, without_last)

    # For k > 2, we need to consider the array repeated k times.
    return total_sum + k * without_last - max_sub_array(without_last * (k - 1))

# Example usage:
# max_sub_array_sum_repeated([1, -2, 1, 2, -1], 5, 3) should return 11
