    # Ensure arr1 is the smaller array
    if len(arr1) > len(arr2):
        arr1, arr2 = arr2, arr1
    total_size = n
    half_size = n // 2

    # Helper function to find kth element in merged arrays
    def find_kth(arr1, arr2, k):
        if not arr1:
            return arr2[k]
        if not arr2:
            return arr1[k]
        if k == 0:
            return min(arr1[0], arr2[0])
