import math

def count_binary_seq(n):
    def count_sequences(start, end, current_sum, memo):
        if (start, end, current_sum) in memo:
            return memo[(start, end, current_sum)]
        if start > end:
            return 1 if current_sum == n else 0
        count = 0
        for bit in [0, 1]:
            count += count_sequences(start + 1, end, current_sum + bit, memo)
        memo[(start, end, current_sum)] = count
        return count

    total_sequences = 2 ** (2 * n)
    memo = {}
    invalid_sequences = 2 * count_sequences(0, 2 * n - 1, 0, memo)
    valid_sequences = total_sequences - invalid_sequences
    return valid_sequences

