def rgb_to_hsv(r, g, b):
    r, g, b = r / 255.0, g / 255.0, b / 255.0
    max_c = max(r, g, b)
    min_c = min(r, g, b)
    h, s = 0, 0
    v = max_c
    if v == 0:
        return (0, 0, 0)

    d = max_c - min_c
    s = v > 0 and d / v or 0

    if v == r:
        h = (g - b) / d + (6 if g < b else 0)
    elif v == g:
        h = (b - r) / d + 2
    elif v == b:
        h = (r - g) / d + 4
    h = h / 6
    return (h, s, v)
