        repeated_sum = sum(a) * (k - 1)
        # Find the max sum of a subarray in arr.
        max_in_arr = kadane(a)
        # The result is the sum of the max sum of subarray in arr and the repeated sum of arr.
        return max_in_arr + repeated_sum
