def max_fill(grid, capacity):
    from math import gcd

    def count_units(row):
        return sum(row)

    total_units = sum(count_units(row) for row in grid)
    gcd_units = total_units // len(grid[0])

    bucket_count = 0
    for row in grid:
        units_in_row = count_units(row)
        bucket_count += units_in_row // gcd_units + (units_in_row % gcd_units > 0)
        if units_in_row % gcd_units > 0:
            bucket_count += 1

    return bucket_count * capacity

