def lcs_of_three(X, Y, Z):
    m = len(X)
    n = len(Y)
    p = len(Z)

    # Create a 3D list to store lengths of longest common subsequence
    dp = [[[0 for i in range(p+1)] for j in range(n+1)] for k in range(m+1)]

    # Build the dp array from bottom up
    for i in range(1, m+1):
        for j in range(1, n+1):
            for k in range(1, p+1):
                if X[i-1] == Y[j-1] == Z[k-1]:
                    dp[i][j][k] = dp[i-1][j-1][k-1] + 1
                else:
                    dp[i][j][k] = max(dp[i-1][j][k], dp[i][j-1][k], dp[i][j][k-1])

    # The length of the longest common subsequence is stored in dp[m][n][p]
    return dp[m][n][p]
