def bell_Number(n):
    if n == 0:
        return 1
    if n == 1:
        return 1

    bell = [0] * (n + 1)
    bell[0] = 1

    for i in range(1, n + 1):
        bell[i] = 0
        for j in range(i):
            bell[i] += bell[i - j - 1] * binomial_coeff(i, j)

    return bell[n]

def binomial_coeff(n, k):
    if k > n - k:
        k = n - k
    result = 1
    for m in range(k):
        result = result * (n - m) // (m + 1)
    return result

