    def binomial_coefficient_sum(n, even):
        if n == even:
            return 1
        if n < even:
            return 0
        return binomial_coefficient_sum(n - 1, even) + binomial_coefficient_sum(n - 2, even + 2)

    def binomial_coefficient(n, k):
        if k == 0 or k == n:
            return 1
        return binomial_coefficient(n - 1, k - 1) + binomial_coefficient(n - 1, k)

    # Calculate the sum of even index binomial coefficients
    total_sum = 0
    for k in range(0, n + 1, 2):
        total_sum += binomial_coefficient(n, k)

    return total_sum
