def set_left_most_unset_bit(n):
    # If n is 0, the left-most unset bit is 1
    if n == 0:
        return 1
    # Iterate to find the left-most unset bit
    while True:
        # Check if the current bit is unset
        if n & (1 << (n.bit_length() - 1)):
            break
        # Clear the current bit and move to the next one
        n &= n - 1
    # Set the left-most unset bit
    return n | (1 << (n.bit_length() - 1))

