def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_fib(n: int) -> int:
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    """
    count, a, b = 0, 0, 1
    while count < n:
        if is_prime(b):
            count += 1
            if count == n:
                return b
        a, b = b, a + b
    return -1  # In case n is too large and we reach a point where no more primes are found

