from math import gcd

def find_solution(a, b, n):
    if n < 0 or gcd(a, b) > abs(n):
        return None
    x, y = 0, 0
    a1, b1 = a, b
    while n != 0:
        q, r = divmod(abs(n), gcd(a1, b1))
        if r != 0:
            x = x + q * (a1 // gcd(a1, b1)) * (n // abs(n))
            y = y - q * (b1 // gcd(a1, b1)) * (n // abs(n))
            n = r
            if a1 > b1:
                a1, b1 = b1, a1
            a1, b1 = b1 % a1, a1
        else:
            break
    return (x, y) if n == 0 else None
