def amicable_numbers_sum(limit):
    def sum_divisors(n):
        return sum([i for i in range(1, n) if n % i == 0])

    amicable_pairs = []
    for num in range(2, limit):
        sum1 = sum_divisors(num)
        if sum1 > 1 and sum1 < limit:
            sum2 = sum_divisors(sum1)
            if sum2 == num and (num, sum1) not in amicable_pairs and (sum1, num) not in amicable_pairs:
                amicable_pairs.append((num, sum1))

    return sum([pair[0] for pair in amicable_pairs])

