def lcs_of_three(X, Y, Z):
    m, n, o = len(X), len(Y), len(Z)

    # Initialize a 3D DP array for the longest common subsequence
    dp = [[[0 for _ in range(o + 1)] for _ in range(n + 1)] for _ in range(m + 1)]

    # Build the DP table in bottom-up fashion
    for i in range(m + 1):
        for j in range(n + 1):
