def maxAverageOfPath(cost):
    def dfs(i, j, path_cost, path_count, memo):
        if (i, j) in memo:
            return memo[(i, j)]
        if i == N - 1 and j == N - 1:
            return path_cost / path_count

        # Move right
        if j < N - 1:
            memo[(i, j)] = max(dfs(i, j + 1, path_cost + cost[i][j + 1], path_count + 1, memo),
                                dfs(i, j + 1, path_cost, path_count, memo))
        # Move down
        if i < N - 1:
            memo[(i, j)] = max(dfs(i + 1, j, path_cost + cost[i + 1][j], path_count + 1, memo),
                                dfs(i + 1, j, path_cost, path_count, memo))

        return memo[(i, j)]

    N = len(cost)
    memo = {}
    return dfs(0, 0, cost[0][0], 1, memo)
