def check_expression(exp):
    # Mapping of closing to opening parentheses
    parentheses_map = {')': '(', ']': '[', '}': '{'}
    # Stack to keep track of opening parentheses
    stack = []

    for char in exp:
        # If it's an opening parenthesis, push it onto the stack
        if char in parentheses_map.values():
            stack.append(char)
        # If it's a closing parenthesis, check for a match
        elif char in parentheses_map:
            if stack == [] or parentheses_map[char] != stack.pop():
                return False

    # If the stack is empty, all parentheses were matched correctly
    return stack == []
