def newman_prime(n):
    from sympy import isprime

    def find_next_newman_prime(last_prime):
        i = 2 * last_prime + 1
        while not isprime(i):
            i += 2 * last_prime + 2
        return i

    def is_newman_prime(p):
        if p < 2:
            return False
        for k in range(1, 6):
            if not isprime((2 ** k) * p + 1):
                return False
        return True

    last_prime = 2
    count = 1

    while count < n:
        next_prime = find_next_newman_prime(last_prime)
        if is_newman_prime(next_prime):
            count += 1
        last_prime = next_prime

    return last_prime
