def maxAverageOfPath(cost):
    N = len(cost)

    def dfs(r, c, path_cost, path_length):
        nonlocal max_avg, max_path_cost

        if r == N - 1 and c == N - 1:
            max_avg = max(max_avg, path_cost / path_length)
            max_path_cost = max(max_path_cost, path_cost)
            return

        if r < N - 1:
            dfs(r + 1, c, path_cost + cost[r + 1][c], path_length + 1)

        if c < N - 1:
            dfs(r, c + 1, path_cost + cost[r][c + 1], path_length + 1)

    max_avg = 0
    max_path_cost = 0
    dfs(0, 0, cost[0][1], 1)
    return max_avg

