        visited.add((x, y))
        min_path = None
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited:
                candidate = dfs(nx, ny, path + [grid[nx][ny]])
                if min_path is None or candidate < min_path:
                    min_path = candidate
        visited.remove((x, y))
        return min_path

    min_path = dfs(0, 0, [])
    return min_path

