def max_sub_array_sum_repeated(a, n, k):
    def kadane(a, n):
        max_sum = current_sum = a[0]
        for i in range(1, n):
            current_sum = max(a[i], current_sum + a[i])
            max_sum = max(max_sum, current_sum)
        return max_sum

    # If k = 1, we can directly use Kadane's algorithm.
    if k == 1:
        return kadane(a, n)
    # For k > 1, the problem reduces to finding the maximum sum of a subarray in the array a repeated k times.
    # We can do this by finding the maximum subarray sum of the array a repeated k-1 times.
    max_sum = kadane(a * (k - 1), n * (k - 1))
    # Add the sum of the first n elements of the array to the result.
    return max_sum + (n * max(a))

