    def find_min_nested_index(brackets):
        min_index = len(brackets)
        for i, bracket in enumerate(brackets):
            if bracket == '[':
                # Check if the current bracket is nested within another bracket
                if brackets[i + 1:i + 3] == ['[', ']']:
                    min_index = i
        return min_index if min_index != len(brackets) else -1

    # Find the minimum index of a nested bracket
    min_nested_index = find_min_nested_index(s)
    return min_nested_index != len(s)

