def is_polite(n):
    def is_polite_helper(k):
        if k == 1:
            return True
        for i in range(2, k+1):
            if k % i == 0 and is_polite_helper(k // i):
                return True
        return False

    def nth_polite(n):
        count = 0
        num = 1
        while count < n:
            if not is_polite_helper(num):
                count += 1
            num += 1
        return num - 1

    return nth_polite(n)
