def count_Pairs(arr, n):
    # Initialize a dictionary to keep count of each element
    counts = {}
    for num in arr:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    # Calculate the number of possible unordered pairs
    # Each element can pair with all other elements except itself
    # If an element appears once, it can only pair once
    # If an element appears twice, it can pair with the other appearances and with itself once
    total_pairs = 0
    for count in counts.values():
        if count == 1:
            # Element appears once, can pair with one other element
            total_pairs += 1
        else:
            # Element appears more than once, can pair with all others of the same type and with itself
            total_pairs += (count * (count - 1)) // 2
            if count > 1:
                # Can also pair with itself once
                total_pairs += 1
    return total_pairs
