def find_solution(a, b, n):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def extended_gcd(x, y):
        s, old_s = 0, 1
        t, old_t = 1, 0
        r, old_r = y, x
        while r:
            old_r, r = r, r % old_r
            old_s, s = s, old_s - s * (r // old_r)
            old_t, t = t, old_t - t * (r // old_r)
        return old_s, old_t, old_r

    g, s, t = extended_gcd(a, b)
    if n % g:
        return None
    else:
        x = n // g * s * b
        y = n // g * t * a
        return (x, y)
