def digit_distance_nums(n1, n2):
    # Convert integers to strings to iterate over each digit
    str_n1, str_n2 = str(n1), str(n2)
    # Ensure both strings are of equal length by padding with zeros
    len_n1, len_n2 = len(str_n1), len(str_n2)
    if len_n1 < len_n2:
        str_n1 = '0' * (len_n2 - len_n1) + str_n1
    elif len_n2 < len_n1:
