def rearrange_bigger(n):
    digits = list(str(n))
    length = len(digits)

    # Start from the right to find the first digit that is smaller than the digit next to it
    for i in range(length - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            # Find the smallest digit on the right of the current digit that is greater than digits[i]
            for j in range(length - 1, i, -1):
                if digits[j] > digits[i]:
                    # Swap the found digit with digits[i]
                    digits[i], digits[j] = digits[j], digits[i]
                    # Sort the digits to the right of the new position of digits[i]
                    digits[i + 1:] = sorted(digits[i + 1:])
                    return int(''.join(digits))
    # If no such digit is found, return -1 (indicating no bigger number can be formed)
    return -1
