from heapq import heappush, heappop

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    pq = [(grid[0][0], 0, 0)]
    visited = set()

    while k > 0:
        val, x, y = heappop(pq)
        if (x, y) in visited:
            continue
        visited.add((x, y))
        if k == 1:
            return [val]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited:
                heappush(pq, (grid[nx][ny], nx, ny))
        k -= 1
