            return None
        mid = (left + right) // 2
        if mid > left and arr[mid] < arr1[k-1]:
            return binary_search(arr, mid+1, right, k)
        if mid < right and arr[mid] > arr1[k-1]:
            return binary_search(arr, left, mid-1, k)
        return arr[mid]

