def maxAverageOfPath(cost):
    n = len(cost)
    for i in range(1, n):
        cost[0][i] += cost[0][i - 1]
        cost[i][0] += cost[i - 1][0]

    for i in range(1, n):
        for j in range(1, n):
            cost[i][j] += max(cost[i - 1][j], cost[i][j - 1])

    total_cost = cost[n - 1][n - 1]
    cells_visited = n - 1
    max_avg = total_cost / cells_visited

    for i in range(n - 2, -1, -1):
        for j in range(n - 2, -1, -1):
            if cost[i + 1][j] >= cost[i][j + 1]:
                cost[i][j] += cost[i + 1][j]
                cells_visited += 1
            else:
                cost[i][j] += cost[i][j + 1]
                cells_visited += 1
        if n - i - 1 > 0:
            cells_visited += n - i - 1
        else:
            break

    max_avg = max(max_avg, total_cost / cells_visited)
    return max_avg
