def max_sum_increasing_subseq(a, n, index, k):
    def lis_with_k(a, n, index, k):
        lis = [0] * (n + 1)
        dp = [0] * (n + 1)

        for i in range(n - 1, index - 1, -1):
            lis[i] = max(lis[i + 1], a[i])
            dp[i] = max(dp[i + 1], dp[i] + a[i])

