def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    # Initialize the smallest and second smallest elements
    smallest, second_smallest = heapq.nsmallest(2, numbers)
    smallest_diff = abs(smallest - second_smallest)

    # Iterate through the numbers to find the closest pair
    for num in numbers:
        if num == smallest or num == second_smallest:
            continue
        new_diff = abs(num - smallest)
        if new_diff < smallest_diff:
            second_smallest = smallest
            smallest_diff = new_diff
        elif new_diff < abs(second_smallest - smallest):
            second_smallest = num
    return (smallest, second_smallest)
