def unique_sublists(list1):
    from collections import defaultdict

    def flatten(lst):
        for el in lst:
            if isinstance(el, list):
                yield from flatten(el)
            else:
                yield el

    flat_list = list(flatten(list1))
    counts = defaultdict(int)

    for item in flat_list:
        counts[item] += 1

    def to_tuple(item):
        if isinstance(item, list):
            return tuple(to_tuple(subitem) for subitem in item)
        return item

    unique_tuples = {tuple(to_tuple(item)): count for item, count in counts.items()}

    return unique_tuples
