    # Initialize counters for the number of open and nested brackets
    open_count = nested_count = 0

    for char in s:
        if char == '[':
            # Increment open bracket count
            open_count += 1
            # If nested brackets are found, increment nested bracket count
            if nested_count > 0:
                nested_count += 1
        elif char == ']':
            if open_count > 0:
                open_count -= 1
            # Nested brackets can only be nested within open brackets
            else:
                nested_count -= 1
                # If nested brackets are greater than open brackets, return False
                if nested_count < 0:
                    return False

    # If there are nested brackets, return True
    return nested_count > 0

