def count_rotation(arr):
    n = len(arr)
    if n == 0:
        return 0

    low, high = 0, n - 1

    while low <= high:
        if arr[low] <= arr[high]:
            return low

        mid = (low + high) // 2
        next_mid = (mid + 1) % n
        prev_mid = (mid - 1 + n) % n

        if arr[prev_mid] <= arr[mid] <= arr[next_mid]:
            return mid
        elif arr[low] <= arr[mid]:
            low = mid + 1
        else:
            high = mid - 1

    return 0
