def babylonian_squareroot(number):
    if number < 0:
        raise ValueError("Cannot compute square root of a negative number")
    if number == 0:
        return 0

    # Initial guess will be half of the number
    guess = number / 2.0

    # Continue until guess is close to the actual square root
    while True:
        better_guess = (guess + number / guess) / 2.0
        if abs(better_guess - guess) < 1e-10:  # Small threshold for floating point comparison
            return better_guess
        guess = better_guess

