def min_Swaps(str1, str2):
    str1_len = len(str1)
    str2_len = len(str2)
    if str1_len != str2_len:
        return -1

    # Create a dictionary to store the positions of '1's in both strings
    pos1 = {str1[i]: i for i in range(str1_len) if str1[i] == '1'}
    pos2 = {str2[i]: i for i in range(str2_len) if str2[i] == '1'}

    # Calculate the minimum swaps required
    swaps = 0
    for pos in pos1:
        if pos in pos2:
            swaps += 1
        else:
            pos2[pos] = min(pos2[k] for k in pos2.keys() if k > pos)  # Reassign the position to the next available position

    return swaps
