def min_Jumps(steps, d):
    def jump(steps, d, memo):
        if d == 0:
            return 0
        if d < 0:
            return float('inf')

        if d in memo:
            return memo[d]

        memo[d] = min(
            jump(steps, d - steps, memo) + 1,
            jump(steps, d + steps, memo) + 1
        )
        return memo[d]

    # Add 0 to the steps to handle cases where d is negative or zero
    memo = {}
    return jump(steps + [0], d, memo)
