def rearrange_bigger(n):
    digits = list(map(int, str(n)))
    length = len(digits)

    # Find the first digit 'd' from right to left such that d is smaller than the digit next to it
    for i in range(length - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            # Find the smallest digit on the right of 'd' that is larger than 'd'
            for j in range(length - 1, i, -1):
                if digits[j] > digits[i]:
                    # Swap the found digits
                    digits[i], digits[j] = digits[j], digits[i]
                    # Sort the digits after the position 'i' to get the smallest possible number
                    digits[i+1:] = sorted(digits[i+1:])
                    # Convert the list of digits back to an integer
                    return int(''.join(map(str, digits)))
    # If no such 'd' exists, the number is already the largest rearrangement possible
    return -1
