def pancake_sort(nums):
    def flip(arr, k):
        for i in range(k // 2):
            arr[i], arr[k - i - 1] = arr[k - i - 1], arr[i]

    def sort(nums):
        n = len(nums)
        for i in range(n):
            max_idx = nums.index(max(nums[:n - i]))
            if max_idx != i:
